// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: caller address (actor) and an unlockTime candidate
    function testFuzz_property(address actor, uint256 unlockTime, uint256 value) public {
        // Keep domains wide but sensible
        vm.assume(actor != address(0));
        // value should be small enough to fund easily in tests but allow zero too
        value = bound(value, 0, 5 ether);
        // Give actor Ether to send
        vm.deal(actor, value);

        // Ensure we are at a known timestamp baseline; allow fuzzer to move time widely
        // keep block time in reasonable range but allow wide fuzzing
        uint256 t = bound(block.timestamp, 1, type(uint256).max - 1000);
        vm.warp(t);

        // Make the call from actor sending value and the fuzzed unlockTime
        bool ok;
        vm.prank(actor);
        try c.Put{value: value}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property (single assertion): for the correct reference implementation,
        // whenever Put returns (succeeds) the stored unlockTime for actor is >= block.timestamp;
        // the mutant that sets acc.unlockTime = _unlockTime can make it < block.timestamp for some inputs.
        // We assert the property on the contract's public Acc mapping getter: Acc(actor).unlockTime >= block.timestamp
        // If the call reverted, the state didn't change and the getter will reflect pre-state (which still satisfies >= block.timestamp for zero-initialized unlockTime if warp>=0),
        // so we assert regardless of ok.

        // read stored unlockTime via public mapping getter: Acc returns (uint unlockTime, uint balance)
        (uint storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime >= block.timestamp);
    }
}

