pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amt, uint256 unlock) public {
        // keep amounts reasonable and ensure caller is not the zero address
        vm.assume(caller != address(0));
        // bound amount to a sensible range so vm.deal is usable
        amt = bound(amt, 0, 5 ether);

        // fund caller so they can send wei
        vm.deal(caller, amt);

        // perform the call as caller, sending amt wei and provided unlock
        vm.prank(caller);
        bool ok;
        try c.Put{value: amt}(unlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C must always ensure that c.Acc(caller).unlockTime >= block.timestamp
        // immediately after the call completes. We observe this via the public getter for Acc.
        // If the Put reverted then we cannot observe state change; in that case the property is vacuously true.
        if (ok) {
            // read the stored unlockTime
            (, uint storedUnlock) = c.Acc(caller);
            // general rule: storedUnlock >= current block.timestamp
            assertTrue(storedUnlock >= block.timestamp);
        } else {
            // If Put reverted, there is no state change; assert true to satisfy single assert requirement
            assertTrue(true);
        }
    }
}

