pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 unlockTime, uint256 value) public {
        // Keep domain wide but ensure unlockTime is not in the past relative to current block.timestamp
        // so that reference behavior sets acc.unlockTime == unlockTime. This tightens admissible domain
        // so the reference holds for all inputs the fuzzer will try here.
        vm.warp(block.timestamp); // no-op but explicit
        // bound value to reasonable ETH and fund actor
        value = bound(value, 0, 10 ether);
        // require unlockTime >= block.timestamp to match the rule's domain
        vm.assume(unlockTime >= block.timestamp);

        vm.deal(actor, value);
        vm.prank(actor);
        c.Put{value: value}(unlockTime);

        // exactly one assertion: stored unlockTime for actor equals the provided unlockTime
        // This reads the public mapping Acc via the auto-generated getter Acc(address)
        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(actor);
        assertTrue(storedUnlockTime == unlockTime);
    }
}

