import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit, uint256 suppliedUnlock, address actor) public {
        // keep deposit reasonable (must be >= MinSum possibly to allow Collect later, but here we only call Put)
        deposit = bound(deposit, 0, 10 ether);
        // actor must be non-zero
        vm.assume(actor != address(0));

        // fund actor so they can send Ether with Put when deposit>0
        vm.deal(actor, deposit);

        // capture current block timestamp
        uint256 before = block.timestamp;

        // perform Put from actor with fuzzed deposit and suppliedUnlock
        vm.prank(actor);
        if (deposit > 0) {
            c.Put{value: deposit}(suppliedUnlock);
        } else {
            // allow zero-value calls as well
            c.Put{value: 0}(suppliedUnlock);
        }

        // After Put returns, the stored unlockTime for actor must be >= the call-time block.timestamp (before)
        // This is the single invariant asserted. The mutant that forces acc.unlockTime = block.timestamp
        // will make acc.unlockTime equal to before and thus can be < suppliedUnlock when suppliedUnlock > before,
        // which violates intended behavior where unlockTime should be max(suppliedUnlock, block.timestamp).
        uint256 recorded = c.Acc(actor).unlockTime;
        assertTrue(recorded >= before);
    }
