pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor (who calls Put), amount to send, and an unlockTime value
    function testFuzz_property(address actor, uint256 amount, uint256 _unlockTime) public {
        // keep amount reasonable (but wide); allow 0 too
        amount = bound(amount, 0, 10 ether);
        // ensure actor is not zero address
        vm.assume(actor != address(0));

        // make _unlockTime be in the future relative to current block timestamp for the distinguishing case
        // but don't force it always; we want the property to hold universally, and the mutant to fail for some
        // Construct a future unlock time by ensuring it's at least block.timestamp + 1
        uint256 futureUnlock = _unlockTime;
        if (futureUnlock <= block.timestamp) {
            futureUnlock = block.timestamp + 1 + (futureUnlock % 1000);
        }

        // fund actor and call Put as that actor, sending Ether
        vm.deal(actor, amount + 1 ether); // ensure they have funds
        vm.prank(actor);
        // perform payable call; capture success via try/catch on low-level call to keep within allowed readings
        bool ok;
        try c.Put{value: amount}(futureUnlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful Put, the correct contract guarantees stored unlockTime >= provided _unlockTime
        // We assert that whenever the call succeeded, c.Acc(actor).unlockTime >= futureUnlock
        // Access the public mapping getter: Acc returns (uint256 unlockTime, uint256 balance)
        if (ok) {
            (uint256 storedUnlock, ) = c.Acc(actor);
            assertTrue(storedUnlock >= futureUnlock);
        } else {
            // If the call reverted, we still assert ok is false (single assert required), so map to false case
            // but we must make exactly one assertTrue covering the universal property; therefore, assert that ok implies the relation
            // express as: ok == (storedUnlock >= futureUnlock) can't be done without reading storedUnlock when ok==false.
            // To keep a single assertTrue reading c: when call failed, we assert that stored unlock time is >= futureUnlock
            // However if call failed, stored state didn't change, but original may still satisfy; we simply assert true==true via stored check
            (uint256 storedUnlock, ) = c.Acc(actor);
            assertTrue(storedUnlock >= futureUnlock || !ok);
        }
    }
}

