pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz params: actor address, initial deposit amount, initial unlockTime offset, new deposit amount, new _unlockTime offset
    // The property: calling Put should NOT decrease the stored unlockTime for an account.
    // We fuzz values so the fuzzer can find cases where mutant decreases unlockTime.
    function testFuzz_property(address actor, uint256 initAmt, int256 initOffset, uint256 newAmt, int256 newOffset) public {
        // keep actor non-zero
        if (actor == address(0)) return;

        // bound amounts to reasonable ranges but keep wide
        initAmt = bound(initAmt, 0, 5 ether);
        newAmt = bound(newAmt, 0, 5 ether);

        // interpret offsets as seconds relative to block.timestamp; allow negative/positive but bound magnitude
        initOffset = int256(bound(uint256(uint256(int256(initOffset < 0 ? uint256(uint256(-initOffset)) : uint256(uint256(initOffset))))), 0, 365 days));
        newOffset = int256(bound(uint256(uint256(int256(newOffset < 0 ? uint256(uint256(-newOffset)) : uint256(uint256(newOffset))))), 0, 365 days));

        // compute absolute unlock times: these may be in past or future
        uint256 initUnlock = (initOffset >= 0) ? block.timestamp + uint256(initOffset) : block.timestamp - uint256(-initOffset);
        uint256 newUnlock = (newOffset >= 0) ? block.timestamp + uint256(newOffset) : block.timestamp - uint256(-newOffset);

        // Give actor funds and perform initial Put to set a baseline unlockTime
        vm.deal(actor, initAmt + 1 ether); // ensure enough balance
        vm.prank(actor);
        if (initAmt > 0) {
            c.Put{value: initAmt}(initUnlock);
        } else {
            // even zero deposit allowed: call with 0 value
            c.Put{value: 0}(initUnlock);
        }

        // Read stored unlockTime after initial Put
        uint256 storedBefore = c.Acc(actor).unlockTime;

        // Now perform a second Put that may try to lower the unlockTime
        vm.deal(actor, newAmt + 1 ether);
        vm.prank(actor);
        if (newAmt > 0) {
            c.Put{value: newAmt}(newUnlock);
        } else {
            c.Put{value: 0}(newUnlock);
        }

        uint256 storedAfter = c.Acc(actor).unlockTime;

        // General rule: the stored unlockTime MUST NOT decrease after a Put (it should be at least storedBefore)
        // This holds in reference implementation (it takes max of previous and provided and block.timestamp),
        // but the mutant that unconditionally sets block.timestamp can decrease unlockTime below storedBefore.
        assertTrue(storedAfter >= storedBefore);
    }
}

