pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz: actor address and a proposed new unlock time; also deposit amount
    function testFuzz_property(address actor, uint256 newUnlockTime, uint256 deposit) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound deposit to a reasonable range but allow zero as well
        deposit = bound(deposit, 0, 10 ether);

        // initial funding so actor can send deposit
        vm.deal(actor, deposit);

        // establish an initial unlockTime by calling Put once with some prior value
        uint256 prior = block.timestamp + 1 days;
        vm.prank(actor);
        if (deposit > 0) {
            c.Put{value: deposit}(prior);
        } else {
            // if deposit is zero still call Put to set unlockTime
            c.Put{value: 0}(prior);
        }

        // read stored prior unlockTime via public getter Acc
        (uint256 storedBefore, ) = c.Acc(actor);

        // now advance time backwards is impossible; instead we can warp to an earlier timestamp
        // but warp can only move forward. To make block.timestamp potentially less than storedBefore,
        // pick a newUnlockTime that is less than storedBefore and warp forward so block.timestamp < storedBefore
        // Ensure block.timestamp is earlier than storedBefore by warping to storedBefore - 1 day
        uint256 targetWarp = storedBefore > 1 days ? storedBefore - 1 days : 0;
        vm.warp(targetWarp);

        // perform Put with fuzzed newUnlockTime and possibly new deposit
        vm.deal(actor, deposit);
        vm.prank(actor);
        if (deposit > 0) {
            c.Put{value: deposit}(newUnlockTime);
        } else {
            c.Put{value: 0}(newUnlockTime);
        }

        // read stored after
        (uint256 storedAfter, ) = c.Acc(actor);

        // The general invariant: Put must not decrease the previously stored unlockTime
        // i.e., storedAfter >= storedBefore
        assertTrue(storedAfter >= storedBefore);
    }
}

