import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz: actor and proposed unlock time and deposit amount
    function testFuzz_property(address actor, uint256 _unlockTime, uint256 deposit) public {
        vm.assume(actor != address(0));
        // keep deposit reasonable (but wide) to avoid overflow/insufficient funds in test harness
        uint256 amt = bound(deposit, 0, 10 ether);

        // ensure actor has funds
        vm.deal(actor, amt);

        // record prior unlockTime for actor
        (uint256 priorUnlockTime, ) = getHolder(actor);

        // perform Put as actor sending amt value
        vm.prank(actor);
        bool ok;
        try c.Put{value: amt}(_unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Put returns (whether succeeded or not), read new unlockTime via public getter
        (uint256 newUnlockTime, ) = getHolder(actor);

        // The reference contract always ensures that if Put succeeded, unlockTime_new >= max(priorUnlockTime, block.timestamp)
        // We assert the universal property only when Put succeeded: then unlockTime must be >= block.timestamp and >= prior
        if (ok) {
            // single assertion required
            assertTrue(newUnlockTime >= priorUnlockTime && newUnlockTime >= block.timestamp);
        } else {
            // If Put reverted, we still must assert something true for all inputs. When Put reverts, the state must be unchanged:
            // newUnlockTime == priorUnlockTime
            assertTrue(newUnlockTime == priorUnlockTime);
        }
    }

    // helper to read the public struct mapping Acc via its auto-generated getter
    function getHolder(address a) internal view returns (uint256 unlockTime, uint256 balance) {
        (unlockTime, balance) = c.Acc(a);
    }
