contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: deposit some amount < MinSum, then try to Collect that amount.
    // Observe contract balance before and after; on P the balance must not decrease, on M it can.
    function runTest(uint putAmount, uint collectAmount, uint unlockTime) public payable {
        // Preconditions for meaningful test
        require(putAmount > 0, "putAmount>0");
        require(collectAmount > 0, "collectAmount>0");
        // caller must send enough to this test to forward to c
        require(address(this).balance >= putAmount, "insufficient balance for put");

        // ensure we're depositing less than MinSum
        uint minSum = c.MinSum();
        require(putAmount < minSum, "putAmount must be < MinSum");
        // and try to collect at most the deposited amount
        require(collectAmount <= putAmount, "collectAmount <= putAmount");

        // Deposit into c from this contract
        c.Put{value: putAmount}(unlockTime);

        // record c balance before collect
        uint before = address(c).balance;

        // attempt to collect (note: Collect is payable in original contract)
        c.Collect(collectAmount);

        // record after
        uint after = address(c).balance;

        // Property: if the account's recorded balance is < MinSum then Collect must not reduce the contract's balance
        // We observe recorded balance via public getter Acc(address) which returns (unlockTime, balance) tuple; Solidity auto-generates accessor.
        (, uint recordedBalance) = c.Acc(address(this));

        // Assert the invariant: when recordedBalance < MinSum then contract balance did not decrease
        assert(!(recordedBalance < minSum) || after >= before);
    }

    // Allow receiving ETH so tests can fund this contract
    receive() external payable {}
}

